def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_op = op[-1]

    # Count opponent's recent cooperation.
    w = min(10, n)
    recent_c = 0
    for i in range(n - w, n):
        if op[i] == 'C':
            recent_c += 1
    recent_rate = recent_c / w

    # Total cooperation stats.
    total_c = 0
    for a in op:
        if a == 'C':
            total_c += 1
    total_rate = total_c / n

    # Tail run of opponent moves.
    tail_val = op[-1]
    tail_len = 0
    for i in range(n - 1, -1, -1):
        if op[i] == tail_val:
            tail_len += 1
        else:
            break

    remaining = 100 - n

    # Against a sustained defector, defect and only probe rarely.
    if n >= 8 and recent_rate <= 0.15:
        # rare unilateral cooperation probe to catch ALLD that flips
        if tail_len >= 8:
            if n % 25 == 0:
                return 'C'
        return 'D'

    # Opponent just defected.
    if last_op == 'D':
        # If opponent generally very cooperative, forgive isolated defections.
        if total_rate >= 0.75 and tail_len == 1 and n >= 6:
            return 'C'
        # If opponent is moderately cooperative and this is short streak,
        # retaliate once then return to cooperation (TFT-like).
        if total_rate >= 0.5 and tail_len <= 2:
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If opponent has been highly cooperative, reciprocate but exploit near the end.
    if total_rate >= 0.85:
        if remaining <= 1:
            return 'D'
        if remaining <= 3 and recent_rate >= 0.9:
            return 'D'
        return 'C'

    # Moderately cooperative opponent: reciprocate, with occasional probing.
    if recent_rate >= 0.6:
        if remaining <= 2:
            if rng.random() < 0.5:
                return 'D'
        # occasional probe when long CC streak
        return 'C'

    # Mixed opponent: use TFT with forgiveness to rebuild cooperation.
    if recent_rate >= 0.35:
        if tail_len >= 3 and tail_val == 'C':
            # after sustained cooperation, don't rock the boat
            if remaining <= 1:
                return 'D'
            return 'C'
        if n >= 3 and op[-2] == 'D' and last_op == 'C':
            return 'C'
        return 'C'

    # Recent rate low but total not tiny -> still some defection; be cautious.
    if remaining <= 2:
        return 'D'
    if rng.random() < 0.3:
        return 'C'
    return 'D'
